<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#152238"><title>Controle de Chaves</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-sRIl4kxILFvY47J16cr9ZwB07vP4J8+LH7qKQnuqkuIAvNWLzeN8tE5YBujZqJLB" crossorigin="anonymous">
  <style>
    :root{--ink:#172338;--muted:#768398;--blue:#245bd3;--canvas:#f3f6fa;--line:#e8edf3}*{box-sizing:border-box}body{background:var(--canvas);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",sans-serif}.navbar{background:var(--ink);min-height:62px}.navbar-brand{font-weight:700;letter-spacing:.01em}.brand-mark{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#294e8d;color:#fff;margin-right:9px}.app-wrap{max-width:1240px}.page-title{font-size:1.65rem;font-weight:700;letter-spacing:-.035em}.page-subtitle{color:var(--muted);font-size:.91rem}.card{border:1px solid var(--line);border-radius:13px;box-shadow:0 3px 14px rgba(26,44,72,.035)}.metric-card .metric-label,.muted{color:var(--muted);font-size:.79rem}.metric-card .metric-value{font-size:2rem;font-weight:750;line-height:1.2}.metric-icon{height:38px;width:38px;border-radius:11px;display:grid;place-items:center;background:#edf3ff;color:var(--blue);font-weight:700}.metric-green{background:#eaf7ef;color:#16804a}.metric-orange{background:#fff3e4;color:#d77b12}.table thead th{color:#65738a;text-transform:uppercase;font-size:.69rem;letter-spacing:.055em;font-weight:650;border-bottom-color:var(--line);padding:13px 14px}.table tbody td{padding:14px;font-size:.84rem;vertical-align:middle;border-color:#eef1f5}.form-control,.form-select{background-color:#f7f9fc;border-color:#e6ebf1;font-size:.86rem;padding:.65rem .75rem}.form-control:focus,.form-select:focus{background:#fff;border-color:#9eb9f4;box-shadow:0 0 0 .2rem rgba(36,91,211,.1)}.btn-primary{--bs-btn-bg:var(--blue);--bs-btn-border-color:var(--blue);--bs-btn-hover-bg:#194bb8;--bs-btn-hover-border-color:#194bb8}.section-title{font-size:1rem;font-weight:700}.badge-soft{background:#e9f7ef;color:#187849}.badge-busy{background:#fff2df;color:#b56811}.badge-done{background:#edf1f6;color:#637086}.view{display:none}.view.active{display:block}.login-page{min-height:calc(100vh - 62px);display:grid;place-items:center}.login-card{width:min(100%,410px)}.login-logo{background:var(--ink);color:white;border-radius:10px;padding:10px 14px;display:inline-block;font-weight:700}.search-box{max-width:320px}.toast-wrap{z-index:1080}.empty-row{text-align:center;color:var(--muted);padding:30px!important}.mobile-label{display:none}@media(max-width:575.98px){.page-title{font-size:1.4rem}.app-wrap{padding-left:16px;padding-right:16px}.table-responsive{margin:0 -12px}.mobile-label{display:inline;color:var(--muted)}}
    .navbar.fixed-bottom{background:#fff;min-height:auto}
  </style>
</head>
<body>
<nav class="navbar navbar-dark"><div class="container app-wrap"><a class="navbar-brand" href="#dashboard" data-page="dashboard"><span class="brand-mark">⌁</span>Controle de Chaves</a><div class="d-flex align-items-center gap-3"><span id="nav-user" class="text-white-50 small d-none d-sm-inline">Olá, Administrador</span><button id="logout" class="btn btn-sm btn-outline-light d-none" type="button">Sair</button></div></div></nav>
<main class="container app-wrap py-4 py-lg-5">
<section class="view active" id="login"><div class="login-page"><div class="card login-card p-4 p-md-5"><div class="text-center mb-4"><span class="login-logo">Controle de Chaves</span><h1 class="h4 fw-bold mt-4 mb-1">Acesso ao sistema</h1><p class="page-subtitle mb-0">Entre com seus dados para continuar.</p></div><form id="login-form"><label class="form-label small fw-semibold" for="email">E-mail</label><input class="form-control mb-3" id="email" type="email" placeholder="usuario@empresa.com" required><label class="form-label small fw-semibold" for="password">Senha</label><input class="form-control mb-4" id="password" type="password" placeholder="Sua senha" required><button class="btn btn-primary w-100" type="submit">Entrar</button><p class="text-center text-secondary small mt-3 mb-0">Demonstração: informe qualquer e-mail e senha.</p></form></div></div></section>
<section class="view" id="dashboard"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h1 class="page-title mb-1">Dashboard</h1><p class="page-subtitle mb-0">Visão geral do controle de chaves.</p></div><button class="btn btn-primary" data-page="loan">＋ Registrar empréstimo</button></div><div class="row g-3 mb-4"><div class="col-12 col-sm-6 col-lg-3"><div class="card metric-card p-3 p-lg-4 h-100"><div class="d-flex justify-content-between"><span class="metric-label">Total de chaves</span><span class="metric-icon">⌘</span></div><div id="metric-total" class="metric-value text-primary mt-2">0</div><span class="metric-label">Cadastradas no sistema</span></div></div><div class="col-12 col-sm-6 col-lg-3"><div class="card metric-card p-3 p-lg-4 h-100"><div class="d-flex justify-content-between"><span class="metric-label">Disponíveis</span><span class="metric-icon metric-green">✓</span></div><div id="metric-free" class="metric-value text-success mt-2">0</div><span class="metric-label">Prontas para empréstimo</span></div></div><div class="col-12 col-sm-6 col-lg-3"><div class="card metric-card p-3 p-lg-4 h-100"><div class="d-flex justify-content-between"><span class="metric-label">Emprestadas</span><span class="metric-icon metric-orange">↗</span></div><div id="metric-busy" class="metric-value text-warning mt-2">0</div><span class="metric-label">Aguardando devolução</span></div></div><div class="col-12 col-sm-6 col-lg-3"><div class="card metric-card p-3 p-lg-4 h-100"><span class="metric-label">Ações rápidas</span><div class="d-grid gap-2 mt-3"><button class="btn btn-outline-primary btn-sm text-start" data-page="loan">＋ Registrar empréstimo</button><button class="btn btn-outline-secondary btn-sm text-start" data-page="keys">⌘ Cadastrar chave</button></div></div></div></div><div class="card p-3 p-md-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title mb-0">Últimos empréstimos</h2><button class="btn btn-sm btn-link text-decoration-none" data-page="history">Ver histórico →</button></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Chave</th><th>Responsável</th><th>Data e hora</th><th>Situação</th><th></th></tr></thead><tbody id="recent-table"></tbody></table></div></div></section>
<section class="view" id="keys"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h1 class="page-title mb-1">Gerenciamento de Chaves</h1><p class="page-subtitle mb-0">Cadastre, consulte e acompanhe a disponibilidade.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#key-modal">＋ Nova chave</button></div><div class="card p-3 p-md-4"><div class="d-flex flex-wrap justify-content-between gap-3 align-items-center mb-3"><h2 class="section-title mb-0">Chaves cadastradas</h2><input id="key-search" class="form-control search-box" type="search" placeholder="Buscar chave ou local…" aria-label="Buscar chave ou local"></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Chave</th><th>Local</th><th>Status</th><th>Ações</th></tr></thead><tbody id="keys-table"></tbody></table></div></div></section>
<section class="view" id="loan"><div class="mb-4"><h1 class="page-title mb-1">Registrar Empréstimo</h1><p class="page-subtitle mb-0">Informe a chave e a pessoa responsável.</p></div><div class="row justify-content-center"><div class="col-12 col-lg-7 col-xl-6"><div class="card p-4 p-md-5"><h2 class="section-title mb-4">Nova movimentação</h2><form id="loan-form"><label class="form-label small fw-semibold" for="loan-key">Chave</label><select class="form-select mb-3" id="loan-key" required></select><label class="form-label small fw-semibold" for="loan-person">Responsável</label><input class="form-control mb-3" id="loan-person" placeholder="Nome do responsável" required maxlength="80"><label class="form-label small fw-semibold" for="loan-note">Observação <span class="fw-normal text-secondary">(opcional)</span></label><input class="form-control mb-4" id="loan-note" placeholder="Ex.: reunião na sala 2" maxlength="120"><button class="btn btn-primary w-100" type="submit">Registrar empréstimo</button></form></div></div></div></section>
<section class="view" id="history"><div class="mb-4"><h1 class="page-title mb-1">Histórico de Movimentações</h1><p class="page-subtitle mb-0">Consulte os empréstimos e devoluções registrados.</p></div><div class="card p-3 p-md-4"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Chave</th><th>Responsável</th><th>Movimentação</th><th>Situação</th></tr></thead><tbody id="history-table"></tbody></table></div></div></section>
</main>
<nav id="main-nav" class="navbar fixed-bottom bg-white border-top py-1 d-none"><div class="container app-wrap d-flex justify-content-around"><button class="btn btn-sm btn-light" data-page="dashboard">Dashboard</button><button class="btn btn-sm btn-light" data-page="keys">Chaves</button><button class="btn btn-sm btn-light" data-page="loan">Empréstimo</button><button class="btn btn-sm btn-light" data-page="history">Histórico</button></div></nav>
<div class="modal fade" id="key-modal" tabindex="-1" aria-labelledby="key-modal-title" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0 rounded-4"><form id="key-form"><div class="modal-header border-0 pb-0"><h2 class="modal-title fs-5 fw-bold" id="key-modal-title">Cadastrar chave</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body"><label class="form-label small fw-semibold" for="new-key-name">Nome da chave</label><input class="form-control mb-3" id="new-key-name" placeholder="Ex.: 023 — Sala de reunião" maxlength="80" required><label class="form-label small fw-semibold" for="new-key-place">Local</label><input class="form-control" id="new-key-place" placeholder="Ex.: Bloco A" maxlength="80" required></div><div class="modal-footer border-0 pt-0"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary" type="submit">Salvar chave</button></div></form></div></div></div>
<div class="toast-container toast-wrap position-fixed top-0 end-0 p-3"><div id="notice" class="toast" role="status"><div class="toast-body d-flex justify-content-between align-items-center"><span id="notice-message">Pronto.</span><button class="btn-close" data-bs-dismiss="toast" aria-label="Fechar"></button></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js" integrity="sha384-FKyoEForCGlyvwx9Hj09JcYn3nv7wiPVlz7YYwJrWVcXK/BmnVDxM+D2scQbITxI" crossorigin="anonymous"></script>
<script>
const starterKeys=[{id:1,name:'001 — Recepção',place:'Recepção',busy:false},{id:2,name:'002 — Sala 01',place:'Sala 01',busy:true},{id:3,name:'003 — Almoxarifado',place:'Almoxarifado',busy:false},{id:4,name:'004 — Laboratório',place:'Laboratório',busy:true},{id:5,name:'005 — Sala 10',place:'Sala 10',busy:false},{id:6,name:'006 — Sala 02',place:'Sala 02',busy:false},{id:7,name:'007 — Sala 03',place:'Sala 03',busy:false},{id:8,name:'008 — Sala 04',place:'Sala 04',busy:false},{id:9,name:'009 — Sala 05',place:'Sala 05',busy:false},{id:10,name:'010 — Sala 06',place:'Sala 06',busy:false},{id:11,name:'011 — Sala 07',place:'Sala 07',busy:false},{id:12,name:'012 — Sala 08',place:'Sala 08',busy:false},{id:13,name:'013 — Sala 09',place:'Sala 09',busy:false}];
const starterLoans=[{id:1,key:2,person:'Maria Souza',at:new Date(Date.now()-3600000).toISOString(),returned:false,note:''},{id:2,key:4,person:'João Silva',at:new Date(Date.now()-7200000).toISOString(),returned:false,note:''}];
const storedKeys=JSON.parse(localStorage.getItem('chaves.keys')||'null');let keys=storedKeys? [...storedKeys,...starterKeys.filter(starterKey=>!storedKeys.some(storedKey=>storedKey.id===starterKey.id))]:starterKeys;let loans=JSON.parse(localStorage.getItem('chaves.loans')||'null')||starterLoans;let sequence=Math.max(0,...loans.map(x=>x.id));
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('chaves.keys',JSON.stringify(keys));localStorage.setItem('chaves.loans',JSON.stringify(loans))}function currentLoan(keyId){return loans.find(x=>x.key===keyId&&!x.returned)}function dateLabel(value){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value))}function flash(message){$('#notice-message').textContent=message;bootstrap.Toast.getOrCreateInstance($('#notice')).show()}
function render(){const free=keys.filter(k=>!currentLoan(k.id)).length;$('#metric-total').textContent=keys.length;$('#metric-free').textContent=free;$('#metric-busy').textContent=keys.length-free;const keyQuery=($('#key-search')?.value||'').toLowerCase();$('#keys-table').innerHTML=keys.filter(k=>(k.name+' '+k.place).toLowerCase().includes(keyQuery)).map(k=>{const loan=currentLoan(k.id);return `<tr><td class="fw-semibold">${esc(k.name)}</td><td>${esc(k.place)}</td><td><span class="badge rounded-pill ${loan?'badge-busy':'badge-soft'}">${loan?'Emprestada':'Disponível'}</span></td><td>${loan?`<button class="btn btn-sm btn-outline-primary" data-return="${k.id}">Registrar devolução</button>`:`<button class="btn btn-sm btn-outline-secondary" data-loan="${k.id}">Emprestar</button>`}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty-row">Nenhuma chave encontrada.</td></tr>';const available=keys.filter(k=>!currentLoan(k.id));$('#loan-key').innerHTML='<option value="">Selecione uma chave disponível</option>'+available.map(k=>`<option value="${k.id}">${esc(k.name)} — ${esc(k.place)}</option>`).join('');const sorted=[...loans].sort((a,b)=>new Date(b.at)-new Date(a.at));const line=l=>{const k=keys.find(x=>x.id===l.key);return `<tr><td>${dateLabel(l.at)}</td><td class="fw-semibold">${esc(k?.name||'Chave removida')}</td><td>${esc(l.person)}</td><td>${l.returned?'Devolução':'Empréstimo'}</td><td><span class="badge rounded-pill ${l.returned?'badge-done':'badge-busy'}">${l.returned?'Concluído':'Em aberto'}</span></td></tr>`};$('#history-table').innerHTML=sorted.map(line).join('')||'<tr><td colspan="5" class="empty-row">Nenhuma movimentação registrada.</td></tr>';$('#recent-table').innerHTML=sorted.slice(0,5).map(l=>{const k=keys.find(x=>x.id===l.key);return `<tr><td class="fw-semibold">${esc(k?.name||'Chave removida')}</td><td>${esc(l.person)}</td><td>${dateLabel(l.at)}</td><td><span class="badge rounded-pill ${l.returned?'badge-done':'badge-busy'}">${l.returned?'Concluído':'Em aberto'}</span></td><td>${!l.returned?`<button class="btn btn-sm btn-link" data-return="${k?.id}">Devolver</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty-row">Nenhuma movimentação registrada.</td></tr>'}
function go(page){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===page));window.scrollTo({top:0,behavior:'smooth'});render()}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();go(nav.dataset.page)}const loanBtn=e.target.closest('[data-loan]');if(loanBtn){go('loan');$('#loan-key').value=loanBtn.dataset.loan}const returnBtn=e.target.closest('[data-return]');if(returnBtn){const loan=currentLoan(Number(returnBtn.dataset.return));if(loan){loan.returned=true;loan.returnedAt=new Date().toISOString();save();render();flash('Devolução registrada com sucesso.')}}});$('#login-form').addEventListener('submit',e=>{e.preventDefault();$('#logout').classList.remove('d-none');go('dashboard')});$('#logout').addEventListener('click',()=>{go('login');$('#logout').classList.add('d-none')});$('#key-search').addEventListener('input',render);$('#key-form').addEventListener('submit',e=>{e.preventDefault();keys.push({id:Date.now(),name:$('#new-key-name').value.trim(),place:$('#new-key-place').value.trim()});save();render();e.target.reset();bootstrap.Modal.getInstance($('#key-modal')).hide();flash('Chave cadastrada com sucesso.')});$('#loan-form').addEventListener('submit',e=>{e.preventDefault();const key=Number($('#loan-key').value);if(!key)return;loans.unshift({id:++sequence,key,person:$('#loan-person').value.trim(),at:new Date().toISOString(),returned:false,note:$('#loan-note').value.trim()});save();e.target.reset();render();flash('Empréstimo registrado com sucesso.');go('history')});render();
</script>
<script>
$('#login-form').addEventListener('submit',()=>$('#main-nav').classList.remove('d-none'));
$('#logout').addEventListener('click',()=>$('#main-nav').classList.add('d-none'));
</script>
<div style="height:58px"></div>
</body>
</html>
